def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v2 > v1:
        result = 2018
    elif v1 > v2:
        result = 2019
    else:
        result = None

    return {
        "value": result,
        "trace": {
            "v1": v1,
            "v2": v2,
            "comparison": "2018 value is higher than 2019 value" if v2 > v1 else (
                "2019 value is higher than 2018 value" if v1 > v2 else "values are equal"
            ),
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
